-- =============================================================================
-- Migration: 20261010_03_group_management
--
-- Sensitive group operations are implemented as SECURITY DEFINER functions
-- rather than direct client writes, because they need logic that RLS policies
-- cannot express:
--
--   * invitation codes must be generated by the database (gen_random_bytes),
--     not by the browser, or they are guessable;
--   * a group must never be left without an owner;
--   * role changes must not be possible for a plain member.
--
-- Every function re-verifies the caller's own privileges internally. SECURITY
-- DEFINER bypasses RLS, so a function that forgot to check its caller would
-- be a privilege-escalation hole.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Invitations
-- -----------------------------------------------------------------------------

-- Create an invitation for a group the caller owns or administers.
CREATE OR REPLACE FUNCTION public.create_group_invitation(
  p_group_id    uuid,
  p_expires_days integer DEFAULT 7,
  p_max_uses    integer  DEFAULT NULL
)
RETURNS public.group_invitations
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_code    text;
  v_row     public.group_invitations%ROWTYPE;
  v_attempt int := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_group_role(p_group_id, v_uid, ARRAY['owner', 'admin']::text[]) THEN
    RAISE EXCEPTION 'Only a group owner or admin can create invitations'
      USING ERRCODE = '42501';
  END IF;

  IF p_max_uses IS NOT NULL AND p_max_uses < 1 THEN
    RAISE EXCEPTION 'max_uses must be at least 1' USING ERRCODE = '22023';
  END IF;

  IF p_expires_days IS NOT NULL AND (p_expires_days < 1 OR p_expires_days > 365) THEN
    RAISE EXCEPTION 'expires_days must be between 1 and 365' USING ERRCODE = '22023';
  END IF;

  -- 12 random bytes -> 24 hex characters (96 bits of entropy). Generated here,
  -- never in the client, so the code cannot be predicted or brute-forced from
  -- a guessable seed. Retry on the (astronomically unlikely) collision.
  LOOP
    v_code := encode(gen_random_bytes(12), 'hex');
    v_attempt := v_attempt + 1;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.group_invitations WHERE code = v_code);
    IF v_attempt > 5 THEN
      RAISE EXCEPTION 'Could not generate a unique invitation code' USING ERRCODE = '40001';
    END IF;
  END LOOP;

  INSERT INTO public.group_invitations
    (group_id, created_by, code, expires_at, max_uses)
  VALUES (
    p_group_id,
    v_uid,
    v_code,
    CASE WHEN p_expires_days IS NULL THEN NULL
         ELSE now() + make_interval(days => p_expires_days) END,
    p_max_uses
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_group_invitation(uuid, integer, integer)
  TO authenticated;

-- Revoke an existing invitation. The code stops working immediately; the row is
-- kept so the admin can see that it existed and when it was revoked.
CREATE OR REPLACE FUNCTION public.revoke_group_invitation(p_invitation_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_group uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT group_id INTO v_group
  FROM public.group_invitations
  WHERE id = p_invitation_id;

  IF v_group IS NULL THEN
    RAISE EXCEPTION 'Invitation not found' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_group_role(v_group, v_uid, ARRAY['owner', 'admin']::text[]) THEN
    RAISE EXCEPTION 'Only a group owner or admin can revoke invitations'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.group_invitations
  SET revoked_at = COALESCE(revoked_at, now())
  WHERE id = p_invitation_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.revoke_group_invitation(uuid) TO authenticated;

-- -----------------------------------------------------------------------------
-- Membership
-- -----------------------------------------------------------------------------

-- Count the owners in a group. Used to refuse any change that would leave the
-- group ownerless.
CREATE OR REPLACE FUNCTION public.owner_count(p_group_id uuid)
RETURNS integer
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT count(*)::integer
  FROM public.study_group_members
  WHERE group_id = p_group_id AND role = 'owner';
$$;

-- Leave a group yourself.
--
-- An owner cannot simply leave and orphan the group: the caller must transfer
-- ownership or promote someone first. We surface a clear error instead of
-- silently demoting someone.
CREATE OR REPLACE FUNCTION public.leave_group(p_group_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_role   text;
  v_owners integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_role
  FROM public.study_group_members
  WHERE group_id = p_group_id AND user_id = v_uid;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'You are not a member of this group' USING ERRCODE = '22023';
  END IF;

  IF v_role = 'owner' THEN
    v_owners := public.owner_count(p_group_id);
    IF v_owners <= 1 THEN
      RAISE EXCEPTION 'You are the only owner. Transfer ownership before leaving.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  DELETE FROM public.study_group_members
  WHERE group_id = p_group_id AND user_id = v_uid;
END;
$$;

GRANT EXECUTE ON FUNCTION public.leave_group(uuid) TO authenticated;

-- Change a member's role. Owners only: an admin must not be able to promote
-- someone to owner, or demote another owner.
CREATE OR REPLACE FUNCTION public.change_member_role(
  p_group_id uuid,
  p_user_id  uuid,
  p_role     text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_owners  integer;
  v_current text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_role NOT IN ('owner', 'admin', 'member') THEN
    RAISE EXCEPTION 'Invalid role' USING ERRCODE = '22023';
  END IF;

  IF p_user_id = v_uid THEN
    RAISE EXCEPTION 'You cannot change your own role' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_group_role(p_group_id, v_uid, ARRAY['owner']::text[]) THEN
    RAISE EXCEPTION 'Only a group owner can change roles' USING ERRCODE = '42501';
  END IF;

  SELECT role INTO v_current
  FROM public.study_group_members
  WHERE group_id = p_group_id AND user_id = p_user_id;

  IF v_current IS NULL THEN
    RAISE EXCEPTION 'That person is not a member of this group' USING ERRCODE = '22023';
  END IF;

  -- Never leave the group without an owner.
  IF v_current = 'owner' AND p_role <> 'owner' THEN
    v_owners := public.owner_count(p_group_id);
    IF v_owners <= 1 THEN
      RAISE EXCEPTION 'A group must keep at least one owner. Promote someone else first.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE public.study_group_members
  SET role = p_role
  WHERE group_id = p_group_id AND user_id = p_user_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.change_member_role(uuid, uuid, text) TO authenticated;

-- Remove someone from a group. Owners and admins may remove anyone except the
-- last owner; members may remove only themselves.
CREATE OR REPLACE FUNCTION public.remove_group_member(
  p_group_id uuid,
  p_user_id  uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_role    text;
  v_is_self boolean;
  v_owners  integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  v_is_self := (p_user_id = v_uid);

  IF NOT v_is_self
     AND NOT public.has_group_role(p_group_id, v_uid, ARRAY['owner', 'admin']::text[]) THEN
    RAISE EXCEPTION 'Only an owner or admin can remove other members' USING ERRCODE = '42501';
  END IF;

  SELECT role INTO v_role
  FROM public.study_group_members
  WHERE group_id = p_group_id AND user_id = p_user_id;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'That person is not a member of this group' USING ERRCODE = '22023';
  END IF;

  -- An admin cannot remove an owner.
  IF NOT v_is_self
     AND v_role = 'owner'
     AND NOT public.has_group_role(p_group_id, v_uid, ARRAY['owner']::text[]) THEN
    RAISE EXCEPTION 'Only an owner can remove another owner' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'owner' THEN
    v_owners := public.owner_count(p_group_id);
    IF v_owners <= 1 THEN
      RAISE EXCEPTION 'A group must keep at least one owner.' USING ERRCODE = '22023';
    END IF;
  END IF;

  DELETE FROM public.study_group_members
  WHERE group_id = p_group_id AND user_id = p_user_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.remove_group_member(uuid, uuid) TO authenticated;

-- -----------------------------------------------------------------------------
-- Group creation
--
-- Creating a group inserts the group and its owner membership row atomically.
-- A partial create (group with no owner) is not reachable.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_study_group(
  p_name        text,
  p_description text DEFAULT NULL,
  p_visibility  text DEFAULT 'private'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_group_id uuid;
  v_name     text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  v_name := btrim(p_name);
  IF v_name IS NULL OR char_length(v_name) < 1 OR char_length(v_name) > 80 THEN
    RAISE EXCEPTION 'Group name must be 1-80 characters' USING ERRCODE = '22023';
  END IF;

  IF p_visibility NOT IN ('private', 'group') THEN
    RAISE EXCEPTION 'Invalid visibility' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.study_groups (name, description, created_by, visibility)
  VALUES (v_name, NULLIF(btrim(coalesce(p_description, '')), ''), v_uid, p_visibility)
  RETURNING id INTO v_group_id;

  INSERT INTO public.study_group_members (group_id, user_id, role)
  VALUES (v_group_id, v_uid, 'owner');

  RETURN v_group_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_study_group(text, text, text) TO authenticated;